WITH cleaned AS (SELECT *, LENGTH(location) location_length FROM departments WHERE dept_name IN ('Engineering', 'Sales')), with_latest AS (SELECT s.*, latest.employee_job_title FROM cleaned s LEFT JOIN LATERAL (SELECT c.job_title AS employee_job_title FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) latest ON TRUE), enriched AS (SELECT *, FIRST_VALUE(dept_name) IGNORE NULLS OVER (ORDER BY location_length, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_dept_name, LEAD(budget, 2) OVER (PARTITION BY location ORDER BY location_length, id) next_budget, ROW_NUMBER() OVER w_grp row_seq FROM with_latest WINDOW w_grp AS (PARTITION BY dept_name ORDER BY location_length, id)), not_flagged AS (SELECT s.* FROM enriched s WHERE NOT EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND c.email NOT LIKE '%@startup.io')) SELECT id, dept_name, location, budget, location_length, employee_job_title, first_known_dept_name, next_budget FROM not_flagged ORDER BY budget DESC
